#ifndef STDLIB_LAPACK_BASE_DGBTF2_VALIDATION_H
#define STDLIB_LAPACK_BASE_DGBTF2_VALIDATION_H

#include "stdlib/lapack/base/shared.h"
#include "stdlib/lapack/base/xerbla.h"
#include <limits.h>
#include <stddef.h>
#include <stdint.h>

typedef char dgbtf2_lapack_integer_check[ ( sizeof( LAPACK_INT ) <= sizeof( intmax_t ) && (LAPACK_INT)-1 < 0 ) ? 1 : -1 ];
typedef char dgbtf2_blas_integer_check[ ( sizeof( CBLAS_INT ) <= sizeof( intmax_t ) && (CBLAS_INT)-1 < 0 ) ? 1 : -1 ];

typedef struct dgbtf2_envelope {
	uintptr_t first;
	uintptr_t last;
	intmax_t first_index;
	intmax_t last_index;
} dgbtf2_envelope;

/**
* Returns the largest configured LAPACK integer.
*/
static intmax_t dgbtf2_lapack_max( void ) {
	return (intmax_t)( UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( LAPACK_INT ))*CHAR_BIT + 1 ) );
}

/**
* Returns the largest independently configured BLAS integer.
*/
static uintmax_t dgbtf2_blas_max( void ) {
	return UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( CBLAS_INT ))*CHAR_BIT + 1 );
}

/**
* Computes a magnitude without negating a minimum signed integer.
*/
static uintmax_t dgbtf2_magnitude( const intmax_t value ) {
	return value < 0 ? (uintmax_t)( -(value+1) )+1 : (uintmax_t)value;
}

/**
* Computes an exact configured LAPACK product, rejecting overflow.
*/
static int dgbtf2_product( const uintmax_t count, const intmax_t stride, intmax_t *result ) {
	const intmax_t limit = dgbtf2_lapack_max();
	uintmax_t magnitude;
	uintmax_t bound;

	if ( count == 0 || stride == 0 ) {
		*result = 0;
		return 1;
	}
	magnitude = dgbtf2_magnitude( stride );
	bound = (uintmax_t)limit + ( stride < 0 ? 1 : 0 );
	if ( count > bound/magnitude ) return 0;
	magnitude *= count;
	if ( stride < 0 ) {
		*result = magnitude == (uintmax_t)limit+1 ? -limit-1 : -(intmax_t)magnitude;
	} else {
		*result = (intmax_t)magnitude;
	}
	return 1;
}

/**
* Computes an exact configured LAPACK sum, rejecting overflow.
*/
static int dgbtf2_sum( const intmax_t x, const intmax_t y, intmax_t *result ) {
	const intmax_t limit = dgbtf2_lapack_max();
	const intmax_t minimum = -limit-1;

	if ( ( y > 0 && x > limit-y ) || ( y < 0 && x < minimum-y ) ) return 0;
	*result = x+y;
	return 1;
}

/**
* Computes an exact configured LAPACK difference without negating y.
*/
static int dgbtf2_difference( const intmax_t x, const intmax_t y, intmax_t *result ) {
	const intmax_t limit = dgbtf2_lapack_max();
	const intmax_t minimum = -limit-1;

	if ( ( y > 0 && x < minimum+y ) || ( y < 0 && x > limit+y ) ) return 0;
	*result = x-y;
	return 1;
}

/**
* Validates the scalar quartet and the KV/H expressions evaluated on empty.
*/
static LAPACK_INT dgbtf2_dimensions( const int main, const LAPACK_INT M, const LAPACK_INT N, const LAPACK_INT KL, const LAPACK_INT KU, LAPACK_INT *KV, LAPACK_INT *H, LAPACK_INT *K ) {
	intmax_t kv;
	intmax_t h;

	if ( M < 0 ) return main ? -2 : -1;
	if ( N < 0 ) return main ? -3 : -2;
	if ( KL < 0 ) return main ? -4 : -3;
	if ( KU < 0 ) return main ? -5 : -4;
	if ( !dgbtf2_sum( KL, KU, &kv ) ) return main ? -5 : -4;
	if ( !dgbtf2_sum( KL, kv, &h ) || !dgbtf2_sum( h, 1, &h ) ) return main ? -4 : -3;
	*KV = (LAPACK_INT)kv;
	*H = (LAPACK_INT)h;
	*K = M < N ? M : N;
	return 0;
}

/**
* Guards positive-only original scalar transients before their evaluation.
*/
static LAPACK_INT dgbtf2_positive( const int main, const LAPACK_INT M, const LAPACK_INT N, const LAPACK_INT KL, const LAPACK_INT KU, const LAPACK_INT KV, const LAPACK_INT K ) {
	const intmax_t limit = dgbtf2_lapack_max();
	intmax_t terminal;

	if ( M == 0 || N == 0 ) return 0;
	if ( KU > limit-2 ) return main ? -5 : -4;
	if ( K > limit-1 ) return main ? -3 : -2;
	if ( K > limit-KV ) return main ? -5 : -4;
	terminal = KL > M-K ? M : K+KL;
	if ( terminal > limit-1 ) return main ? -2 : -1;
	if ( terminal > limit-KU-1 ) return main ? -5 : -4;
	return 0;
}

/**
* Returns the greatest common divisor of two nonzero magnitudes.
*/
static uintmax_t dgbtf2_gcd( uintmax_t x, uintmax_t y ) {
	uintmax_t remainder;

	while ( y != 0 ) {
		remainder = x%y;
		x = y;
		y = remainder;
	}
	return x;
}

/**
* Checks an aligned inclusive byte envelope without forming derived pointers.
*
* Requiring element-size alignment is conservative on weaker-alignment ABIs.
* Actual allocation capacity, lifetime and hidden physical aliases remain
* caller preconditions. Indices are retained for typed-array extent checks.
*/
static int dgbtf2_envelope_valid( const void *data, const intmax_t first, const intmax_t last, const size_t size, dgbtf2_envelope *envelope ) {
	const uintptr_t address = (uintptr_t)data;
	uintmax_t first_byte;
	uintmax_t last_byte;

	if ( data == NULL || size == 0 || address%size != 0 ) return 0;
	if ( first < 0 || last < first || size-1 > (uintmax_t)PTRDIFF_MAX || (uintmax_t)last > ( (uintmax_t)PTRDIFF_MAX-(size-1) )/size ) return 0;
	first_byte = (uintmax_t)first*size;
	last_byte = (uintmax_t)last*size+(size-1);
	if ( last_byte > UINTPTR_MAX || address > UINTPTR_MAX-(uintptr_t)last_byte ) return 0;
	envelope->first = address+(uintptr_t)first_byte;
	envelope->last = address+(uintptr_t)last_byte;
	envelope->first_index = first;
	envelope->last_index = last;
	return 1;
}

/**
* Tests conservative physical byte-envelope overlap.
*/
static int dgbtf2_overlap( const dgbtf2_envelope *x, const dgbtf2_envelope *y ) {
	return x->first <= y->last && y->first <= x->last;
}

/**
* Checks configured stride products and full-view injectivity (errors 1/2).
*/
static int dgbtf2_matrix_strides_valid( const intmax_t rows, const intmax_t columns, const intmax_t stride1, const intmax_t stride2 ) {
	uintmax_t magnitude1;
	uintmax_t magnitude2;
	uintmax_t divisor;
	intmax_t delta;

	if ( ( rows > 1 && stride1 == 0 ) || !dgbtf2_product( (uintmax_t)(rows-1), stride1, &delta ) ) return 1;
	if ( ( columns > 1 && stride2 == 0 ) || !dgbtf2_product( (uintmax_t)(columns-1), stride2, &delta ) ) return 2;
	if ( rows > 1 && columns > 1 ) {
		magnitude1 = dgbtf2_magnitude( stride1 );
		magnitude2 = dgbtf2_magnitude( stride2 );
		divisor = dgbtf2_gcd( magnitude1, magnitude2 );
		if ( magnitude2/divisor < (uintmax_t)rows && magnitude1/divisor < (uintmax_t)columns ) return 2;
	}
	return 0;
}

/**
* Validates a generic active view, returning offending component 1,2 or 3.
*/
static int dgbtf2_view_valid( const void *data, const intmax_t rows, const intmax_t columns, const intmax_t stride1, const intmax_t stride2, const intmax_t offset, const size_t size, dgbtf2_envelope *envelope ) {
	intmax_t delta1;
	intmax_t delta2;
	intmax_t corner1;
	intmax_t corner2;
	intmax_t corner3;
	intmax_t first;
	intmax_t last;
	int error;

	error = dgbtf2_matrix_strides_valid( rows, columns, stride1, stride2 );
	if ( error != 0 ) return error;
	if ( !dgbtf2_product( (uintmax_t)(rows-1), stride1, &delta1 ) ) return 1;
	if ( !dgbtf2_product( (uintmax_t)(columns-1), stride2, &delta2 ) ) return 2;
	if ( !dgbtf2_sum( offset, delta1, &corner1 ) || !dgbtf2_sum( offset, delta2, &corner2 ) || !dgbtf2_sum( corner1, delta2, &corner3 ) ) return 3;
	first = offset;
	last = offset;
	if ( corner1 < first ) first = corner1;
	if ( corner2 < first ) first = corner2;
	if ( corner3 < first ) first = corner3;
	if ( corner1 > last ) last = corner1;
	if ( corner2 > last ) last = corner2;
	if ( corner3 > last ) last = corner3;
	return dgbtf2_envelope_valid( data, first, last, size, envelope ) ? 0 : 3;
}

/**
* Checks the complete double-precision compact band view.
*/
static int dgbtf2_matrix_valid( const void *data, const intmax_t rows, const intmax_t columns, const intmax_t stride1, const intmax_t stride2, const intmax_t offset, dgbtf2_envelope *envelope ) {
	return dgbtf2_view_valid( data, rows, columns, stride1, stride2, offset, sizeof( double ), envelope );
}

/**
* Guards selected BLAS casts, endpoints, poststeps and compiler trip bounds.
*
* Logical-start pointers have offset zero. Singleton calls normalize the
* unused stride to one. For n>1 the conservative bounds are n<=MAX-2 and
* n*abs(s)+abs(s)+1<=MAX; neither multiplication nor signed negation occurs.
*/
static int dgbtf2_blas_valid( const intmax_t count, const intmax_t stride ) {
	const uintmax_t limit = dgbtf2_blas_max();
	const uintmax_t length = (uintmax_t)count;
	const uintmax_t magnitude = dgbtf2_magnitude( stride );

	if ( count <= 1 ) return 1;
	if ( length > limit-2 || magnitude == 0 || magnitude > limit ) return 0;
	return length+1 <= (limit-1)/magnitude;
}

/**
* Validates every active view and potential selected helper before writes.
*/
static LAPACK_INT dgbtf2_validate( const int main, const LAPACK_INT M, const LAPACK_INT N, const LAPACK_INT KL, const LAPACK_INT KU, const double *AB, const LAPACK_INT strideAB1, const LAPACK_INT strideAB2, const LAPACK_INT offsetAB, const LAPACK_INT *PIV, const LAPACK_INT stridePIV, const LAPACK_INT offsetPIV ) {
	dgbtf2_envelope ab;
	dgbtf2_envelope piv;
	LAPACK_INT kv;
	LAPACK_INT h;
	LAPACK_INT k;
	LAPACK_INT info;
	intmax_t diagonal;
	intmax_t count;
	int error;

	info = dgbtf2_dimensions( main, M, N, KL, KU, &kv, &h, &k );
	if ( info != 0 || M == 0 || N == 0 ) return info;
	info = dgbtf2_positive( main, M, N, KL, KU, kv, k );
	if ( info != 0 ) return info;
	if ( AB == NULL || (uintptr_t)AB%sizeof( double ) != 0 ) return main ? -6 : -5;
	error = dgbtf2_matrix_strides_valid( h, N, strideAB1, strideAB2 );
	if ( error != 0 ) return main ? -6 : (LAPACK_INT)(-5-error);
	diagonal = 1;
	if ( KL > 0 && N > 1 && !dgbtf2_difference( strideAB2, strideAB1, &diagonal ) ) return main ? -6 : -7;
	error = dgbtf2_matrix_valid( AB, h, N, strideAB1, strideAB2, offsetAB, &ab );
	if ( error != 0 ) return main ? -6 : (LAPACK_INT)(-5-error);
	if ( PIV == NULL || (uintptr_t)PIV%sizeof( LAPACK_INT ) != 0 ) return main ? -8 : -9;
	error = dgbtf2_view_valid( PIV, k, 1, stridePIV, 1, offsetPIV, sizeof( LAPACK_INT ), &piv );
	if ( error != 0 ) return main ? -8 : ( error == 1 ? -10 : -11 );
	if ( dgbtf2_overlap( &ab, &piv ) ) return main ? -8 : -9;
	if ( !dgbtf2_blas_valid( KL, strideAB1 ) ) return -6;
	if ( KL > 0 && N > 1 ) {
		count = N < kv+1 ? N : kv+1;
		if ( !dgbtf2_blas_valid( count, diagonal ) ) return main ? -6 : -7;
	}
	return 0;
}

/**
* Prints the adopted LAPACK diagnostic and returns the negative status.
*/
static LAPACK_INT dgbtf2_error( const char *name, const LAPACK_INT info ) {
	API_SUFFIX(lapack_xerbla)( name, info );
	return info;
}

#endif // !STDLIB_LAPACK_BASE_DGBTF2_VALIDATION_H
